        final class Pcm implements SpeakRuntime.Capture,NoteRuntime.Capture {
            final String type;final MicrophoneLease lease;final Queue<short[]> frames=new ConcurrentLinkedQueue<>();short[] frame;int offset;volatile boolean stopping=true,closed;volatile long captured=-1;
            Pcm(String type){this.type=type;lease=MicrophoneLease.acquire("private-routine-audio");if(lease==null)throw new IllegalStateException("Private capture lease occupied");inputs.add(this);}
            public void start(){if(closed)throw new IllegalStateException();}
            public int read(short[] samples){if(closed)throw new IllegalStateException();if(frame==null){frame=frames.poll();offset=0;}if(frame==null)return 0;int count=Math.min(samples.length,frame.length-offset);System.arraycopy(frame,offset,samples,0,count);offset+=count;if(offset==frame.length)frame=null;captured=time.addAndGet(64);return count;}
            public long captured(){return captured;}
            public void close(){if(!stopping)throw new IllegalStateException("Private unconfirmed microphone close");closed=true;frame=null;frames.clear();lease.released();}
            void sound(int windows,double amplitude){for(int n=0;n<windows;n++){short[] frame=new short[15600];Arrays.fill(frame,(short)(amplitude*32767));frames.add(frame);}}
            void notes(int windows,double pitch){for(int n=0;n<windows;n++){short[] frame=new short[NotePitch.SIZE];for(int k=0;k<frame.length;k++)frame[k]=(short)(6000*Math.sin(2*Math.PI*pitch*k/NotePitch.RATE));frames.add(frame);}}
        }
